 'Hot tubs':'<path d="M2 12h20v4a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5zM5 21v2m14-2v2M7 9c-3-3 3-3 0-6m5 6c-3-3 3-3 0-6m5 6c-3-3 3-3 0-6"/>',
