// Hide navigation while moving down, reveal it when moving up.
// On property detail, keep the sticky booking card below the revealed menu (push, don't cover).
let propertyNavJumping=false;
function syncBookingStickyOffset(){
 if(document.body.dataset.step!=='detail'){
  document.body.style.removeProperty('--booking-sticky-top');
  document.body.style.removeProperty('--booking-sticky-gap');
  document.body.style.removeProperty('--property-nav-sticky-top');
  document.body.style.removeProperty('--property-section-offset');
  return;
 }
 const header=$('.header'),nav=$('.property-section-nav');
 const headerTop=header&&!header.classList.contains('header-hidden')?Math.ceil(header.getBoundingClientRect().height):0;
 const navH=nav?Math.ceil(nav.getBoundingClientRect().height):0;
 document.body.style.setProperty('--property-nav-sticky-top',headerTop+'px');
 document.body.style.setProperty('--property-section-offset',(headerTop+navH+16)+'px');
 if(matchMedia('(min-width:851px)').matches){
  document.body.style.setProperty('--booking-sticky-top',(headerTop+navH)+'px');
  document.body.style.setProperty('--booking-sticky-gap','36px');
 }else{
  document.body.style.removeProperty('--booking-sticky-top');
  document.body.style.removeProperty('--booking-sticky-gap');
 }
}
function scrollToPropertySection(id){
 const target=document.getElementById(id);if(!target)return;
 propertyNavJumping=true;
 syncBookingStickyOffset();
 const offset=parseFloat(getComputedStyle(document.body).getPropertyValue('--property-section-offset'))||(($('.property-section-nav')?.offsetHeight||0)+16);
 const top=Math.max(0,scrollY+target.getBoundingClientRect().top-offset);
 const smooth=!matchMedia('(prefers-reduced-motion: reduce)').matches;
 window.scrollTo({top,behavior:smooth?'smooth':'auto'});
 let settled=0,last=scrollY,finished=false;
 const finish=()=>{if(finished)return;finished=true;propertyNavJumping=false;syncBookingStickyOffset()};
 if(!smooth){finish();return}
 const watch=()=>{if(Math.abs(scrollY-last)<1)settled++;else settled=0;last=scrollY;if(settled>8||Math.abs(scrollY-top)<2){finish();return}requestAnimationFrame(watch)};
 requestAnimationFrame(watch);
 setTimeout(finish,1000);
}
{
 const header=$('.header');let previousY=Math.max(0,scrollY),scrollPending=false;
 const revealHeader=()=>{header.classList.remove('header-hidden');syncBookingStickyOffset()};
 const updateHeader=()=>{scrollPending=false;const y=Math.max(0,scrollY),delta=y-previousY;
  // Keep menu/sticky offsets frozen while section-tab jumps are animating.
  if(propertyNavJumping){previousY=y;return}
  header.classList.toggle('header-scrolled',y>10);
  if(y<40||$('#nav').classList.contains('open')||header.contains(document.activeElement)){revealHeader();previousY=y;return}
  if(Math.abs(delta)<8){syncBookingStickyOffset();return}
  header.classList.toggle('header-hidden',delta>0&&y>header.offsetHeight);previousY=y;syncBookingStickyOffset();
 };
 window.addEventListener('scroll',()=>{if(!scrollPending){scrollPending=true;requestAnimationFrame(updateHeader)}},{passive:true});
 window.addEventListener('resize',syncBookingStickyOffset,{passive:true});
 header.addEventListener('focusin',revealHeader);window.addEventListener('pageshow',()=>{previousY=Math.max(0,scrollY);revealHeader()});
 syncBookingStickyOffset();
}


